    def test_reduce_parentheses_binaryops(self):
        c1 = "int x = a + b + c + d;"
        self.assertEqual(self._run_c_to_c(c1), "int x = ((a + b) + c) + d;\n")
        self.assertEqual(
            self._run_c_to_c(c1, reduce_parentheses=True), "int x = a + b + c + d;\n"
        )

        # codes with minimum number of (necessary) parenthesis:
        test_snippets = [
            "int x = a*b*c*d;",
            "int x = a+b*c*d;",
            "int x = a*b+c*d;",
            "int x = a*b*c+d;",
            "int x = (a+b)*c*d;",
            "int x = (a+b)*(c+d);",
            "int x = (a+b)/(c-d);",
            "int x = a+b-c-d;",
            "int x = a+(b-c)-d;",
        ]
        for src in test_snippets:
            src2 = self._assert_ctoc_correct(src, reduce_parentheses=True)
            self.assertTrue(
                src2.count("(") == src.count("("),
                msg=f"{src2!r} did not have minimum number of parenthesis, should be like {src!r}.",
            )


class TestCasttoC(unittest.TestCase):
    def _find_file(self, name):
        test_dir = os.path.dirname(__file__)
        name = os.path.join(test_dir, "c_files", name)
        assert os.path.exists(name)
        return name

    def test_to_type(self):
        src = "int *x;"
        generator = c_generator.CGenerator()
        test_fun = c_ast.FuncCall(c_ast.ID("test_fun"), c_ast.ExprList([]))

        ast1 = parse_to_ast(src)
        int_ptr_type = ast1.ext[0].type
        int_type = int_ptr_type.type
        self.assertEqual(
            generator.visit(c_ast.Cast(int_ptr_type, test_fun)), "(int *) test_fun()"
        )
        self.assertEqual(
            generator.visit(c_ast.Cast(int_type, test_fun)), "(int) test_fun()"
        )

    @unittest.skipUnless(cpp_supported(), "cpp only works on Unix")
    def test_to_type_with_cpp(self):
        generator = c_generator.CGenerator()
        test_fun = c_ast.FuncCall(c_ast.ID("test_fun"), c_ast.ExprList([]))
        memmgr_path = self._find_file("memmgr.h")

        ast2 = parse_file(
            memmgr_path, use_cpp=True, cpp_path=cpp_path(), cpp_args=cpp_args()
        )
        void_ptr_type = ast2.ext[-3].type.type
        void_type = void_ptr_type.type
        self.assertEqual(
            generator.visit(c_ast.Cast(void_ptr_type, test_fun)), "(void *) test_fun()"
        )
        self.assertEqual(
            generator.visit(c_ast.Cast(void_type, test_fun)), "(void) test_fun()"
        )

    def test_nested_else_if_line_breaks(self):
        generator = c_generator.CGenerator()
        test_ast1 = c_ast.If(None, None, None)
        test_ast2 = c_ast.If(None, None, c_ast.If(None, None, None))
        test_ast3 = c_ast.If(
            None, None, c_ast.If(None, None, c_ast.If(None, None, None))
        )
        test_ast4 = c_ast.If(
            None,
            c_ast.Compound([]),
            c_ast.If(
                None, c_ast.Compound([]), c_ast.If(None, c_ast.Compound([]), None)
            ),
        )

        self.assertEqual(generator.visit(test_ast1), "if ()\n  \n")
        self.assertEqual(generator.visit(test_ast2), "if ()\n  \nelse\n  if ()\n  \n")
        self.assertEqual(
            generator.visit(test_ast3),
            "if ()\n  \nelse\n  if ()\n  \nelse\n  if ()\n  \n",
        )
        self.assertEqual(
            generator.visit(test_ast4),
            "if ()\n{\n}\nelse\n  if ()\n{\n}\nelse\n  if ()\n{\n}\n",
        )


